import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, uv, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry } = ctx.THREE;
  const root = new Group();
  const timelines = [];
  const ownedTextures = [];

  const palette = config.intent?.visualSpec?.colors ?? {};
  const ink = palette.ink ?? '#16161d';
  const paper = palette.paper ?? '#e8ecf2';
  const accent = palette.accent ?? '#ff2a38';
  const surface = palette.surface ?? '#0b0b10';

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: false
  });

  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.09, 0.09, 0.122),
      uv().y
    ),
    uv().y
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  backdrop.renderOrder = -10;
  root.add(backdrop);

  const shadowGeometry = new CircleGeometry(1.45, 48);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -0.98, -0.08);
  shadow.rotation.z = 0;
  shadow.scale.set(1.35, 0.34, 1);
  shadow.renderOrder = -2;
  root.add(shadow);

  const spriteGeometry = new PlaneGeometry(3.2, 2);
  const spriteMaterial = new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0,
    depthWrite: false
  });
  spriteMaterial.toneMapped = false;

  const sprite = new Mesh(spriteGeometry, spriteMaterial);
  sprite.position.set(0, 0.12, 0);
  sprite.renderOrder = 2;
  sprite.onBeforeRender = (_renderer, _scene, camera) => {
    sprite.quaternion.copy(camera.quaternion);
  };
  root.add(sprite);

  const accentGeometry = new PlaneGeometry(0.035, 1.05);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0.9,
    depthWrite: false
  });
  const accentLine = new Mesh(accentGeometry, accentMaterial);
  accentLine.position.set(1.48, 0.38, 0.08);
  accentLine.rotation.z = -0.08;
  accentLine.renderOrder = 3;
  root.add(accentLine);

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (!texture) return;

      ownedTextures.push(texture);

      const image = texture.image;
      const atlas = config.atlasRegion ?? {
        x: 0,
        y: 0,
        width: 512,
        height: 320
      };

      if (image?.width && image?.height) {
        texture.repeat.set(
          atlas.width / image.width,
          atlas.height / image.height
        );
        texture.offset.set(
          atlas.x / image.width,
          1 - (atlas.y + atlas.height) / image.height
        );
      }

      spriteMaterial.map = texture;
      spriteMaterial.opacity = 1;
      spriteMaterial.needsUpdate = true;
    }).catch(() => {
      spriteMaterial.opacity = 0;
      spriteMaterial.needsUpdate = true;
    });
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const entry of material) {
          if (entry?.dispose) entry.dispose();
        }
      } else if (material?.dispose) {
        material.dispose();
      }
    });

    for (const texture of ownedTextures) {
      if (texture?.dispose) texture.dispose();
    }

    root.clear();
  };

  return root;
}
